  const track = document.getElementById('icPlansTrack'); const move = function (direction) { if (track) track.scrollBy({ left: direction * Math.max(track.clientWidth * .82, 280), behavior: 'smooth' }); }; const prev = document.getElementById('icPlansPrev'); const next = document.getElementById('icPlansNext'); if (prev) prev.addEventListener('click', function () { move(-1); }); if (next) next.addEventListener('click', function () { move(1); });
  const switcher = document.querySelector('.ic-cycle-switch'); const caption = document.getElementById('icCycleCaption'); const updateLinks = function (cycle) { document.querySelectorAll('.ic-price-card a[href*="contrate/"], .ic-price-card .js-ic-dedicado').forEach(function (link) { const attribute = link.matches('a') ? 'href' : 'data-pla-url'; const destination = link.getAttribute(attribute); if (!destination) return; const url = new URL(destination, window.location.href); url.searchParams.set('p', cycle); link.setAttribute(attribute, url.href); }); }; if (switcher) switcher.querySelectorAll('.ic-cycle-option').forEach(function (option) { option.addEventListener('click', function () { const cycle = option.dataset.ciclo; switcher.classList.toggle('is-annual', cycle === 'anual'); switcher.querySelectorAll('.ic-cycle-option').forEach(function (item) { item.classList.toggle('active', item === option); }); document.querySelectorAll('.ic-price-cycle[data-ciclo]').forEach(function (price) { price.hidden = price.dataset.ciclo !== cycle; }); updateLinks(cycle); if (caption) caption.textContent = cycle === 'anual' ? 'Valores exibidos por ano' : 'Valores exibidos por mês'; }); }); updateLinks('mensal');
  const escapeHtml = function (value) { const element = document.createElement('div'); element.textContent = value || ''; return element.innerHTML; };
  document.querySelectorAll('.js-ic-detalhes').forEach(function (button) { button.addEventListener('click', function () { let benefits = []; try { benefits = JSON.parse(button.dataset.beneficios || '[]'); } catch (error) {} const description = button.dataset.plaDescricao || '<p>Mais informações sobre este plano estarão disponíveis em breve.</p>'; const list = benefits.length ? '<div class="mt-4"><h6 class="text-icliv">O que está incluído</h6><ul class="list-unstyled mb-0">' + benefits.map(function (benefit) { return '<li class="mb-2"><i class="fa-solid fa-check text-success me-2"></i>' + escapeHtml(benefit) + '</li>'; }).join('') + '</ul></div>' : ''; SimpleModal.mostrar({ titulo: '<i class="fa-solid fa-circle-info"></i> ' + escapeHtml(button.dataset.plaNome || 'Detalhes do plano'), tamanho: 'modal-lg', corpo: '<div class="mb-3"><span class="badge rounded-pill text-bg-light text-success">' + escapeHtml(button.dataset.plaRotulo || button.dataset.plaTipo || 'Plano') + '</span></div><div class="ic-plan-details-content">' + description + '</div>' + list, rodape: '<button type="button" class="bto bto-phsa-light" data-bs-dismiss="modal"><i class="fa-solid fa-xmark"></i>&nbsp;Fechar</button>' }); }); });
  document.querySelectorAll('.js-ic-dedicado').forEach(function (button) { button.addEventListener('click', function () { let contacts = []; try { contacts = JSON.parse(button.dataset.contatos || '[]'); } catch (error) {} const list = contacts.length ? '<div class="ic-commercial-team">' + contacts.map(function (contact) { const number = String(contact.celular || '').replace(/\D/g, ''); const whatsapp = number.indexOf('55') === 0 ? number : '55' + number; return '<div class="ic-commercial-contact"><span class="ic-commercial-contact-icon"><i class="fa-solid fa-user-tie"></i></span><div><strong>' + escapeHtml(contact.nome) + '</strong><small><a href="https://wa.me/' + whatsapp + '" target="_blank" rel="noopener" class="ic-contact-action"><i class="fa-brands fa-whatsapp"></i> WhatsApp</a> · <a href="mailto:' + encodeURIComponent(contact.email || '') + '" class="ic-contact-action"><i class="fa-solid fa-envelope"></i> ' + escapeHtml(contact.email) + '</a></small></div></div>'; }).join('') + '</div>' : '<div class="alert alert-light border mb-0">Nosso time comercial estará disponível em breve.</div>'; SimpleModal.mostrar({ titulo: '<i class="fa-solid fa-comments"></i> Fale com o time icliv', tamanho: 'modal-lg', corpo: '<p class="text-muted">Vamos entender a realidade do seu negócio e encontrar a melhor configuração para começar.</p>' + list, rodape: '<button type="button" class="bto bto-phsa-light" data-bs-dismiss="modal"><i class="fa-solid fa-xmark"></i>&nbsp;Fechar</button>' }); }); });
});
</script><?php $this->end(); ?>
